        "$type": "RegexToken",
        "regex": "/\\\\/\\\\/#id\\\\s+[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/",
